181		for _, part := range strings.Split(link, ",") {
182			target, rel, ok := strings.Cut(strings.TrimSpace(part), ";")
183			if !ok || !strings.Contains(rel, `rel="next"`) {
184				continue
185			}
186			target = strings.Trim(strings.TrimSpace(target), "<>")
187			base, err := url.Parse(current)
188			if err != nil {
189				return ""
190			}
191			ref, err := url.Parse(target)
192			if err != nil {
193				return ""
194			}
195			if next := base.ResolveReference(ref).String(); next != current {
196				return next
197			}
198		}
199		return ""
