230		if err != nil {
231			return "", fmt.Errorf("fetch token: %w", err)
232		}
233		defer func() { _ = resp.Body.Close() }()
234		if resp.StatusCode != http.StatusOK {
235			return "", fmt.Errorf("token endpoint returned %d", resp.StatusCode)
236		}
237		body, err := io.ReadAll(resp.Body)
238		if err != nil {
239			return "", fmt.Errorf("read token response: %w", err)
240		}
241		var result struct {
242			Token       string `json:"token"`
243			AccessToken string `json:"access_token"`
244		}
245		if err := json.Unmarshal(body, &result); err != nil {
246			return "", fmt.Errorf("decode token response: %w", err)
247		}
248		if result.Token != "" {
249			return result.Token, nil
250		}
251		if result.AccessToken != "" {
252			return result.AccessToken, nil
253		}
254		return "", fmt.Errorf("token response contained no token field")
