package ociresources

import (
	"strings"

	tea "charm.land/bubbletea/v2"

	"github.com/anthnel/devdesk/internal/engine"
)

// filterStops returns the values `r` cycles through: every group that produced
// results, then every individual registry, then off. The group level is what
// makes "everything from this Nexus" one keystroke rather than eight.
func (b *RegistryBrowser) filterStops() []resultFilter {
	seenGroup, seenEntry := map[string]bool{}, map[string]bool{}
	var groups, singles []resultFilter
	for _, t := range b.tags {
		entry := b.entryFor(t.EntryKey)
		if entry != nil && entry.ParentSlug != "" && !seenGroup[entry.ParentSlug] {
			seenGroup[entry.ParentSlug] = true
			groups = append(groups, resultFilter{groupSlug: entry.ParentSlug})
		}
		if !seenEntry[t.EntryKey] {
			seenEntry[t.EntryKey] = true
			singles = append(singles, resultFilter{entryKey: t.EntryKey})
		}
	}
	// A single source has nothing to filter down to.
	if len(singles) <= 1 {
		return nil
	}
	// A group with every result under it says the same thing as "off".
	if len(groups) == 1 && len(groups) == len(seenGroup) && len(singles) == countMembers(b.entries, groups[0].groupSlug) {
		groups = nil
	}
	return append(groups, singles...)
}

// countMembers returns how many entries belong to a group.
func countMembers(entries []browserRegistryEntry, slug string) int {
	n := 0
	for _, e := range entries {
		if e.ParentSlug == slug {
			n++
		}
	}
	return n
}

func (b *RegistryBrowser) cycleRegistryFilter() {
	stops := b.filterStops()
	if len(stops) == 0 {
		b.registryFilter = resultFilter{}
		b.rebuildTagTable()
		return
	}
	if b.registryFilter.isEmpty() {
		b.registryFilter = stops[0]
		b.rebuildTagTable()
		return
	}
	for i, s := range stops {
		if s == b.registryFilter {
			if i+1 < len(stops) {
				b.registryFilter = stops[i+1]
			} else {
				b.registryFilter = resultFilter{} // back to everything
			}
			b.rebuildTagTable()
			return
		}
	}
	b.registryFilter = resultFilter{}
	b.rebuildTagTable()
}

// entryFor returns the browser entry a result came from, or nil.
//
// It resolves by entry key, not by URL: every member of a path-routed group
// answers to the same host, so a URL identifies a whole instance and a result
// would be unattributable (§3.18, and D40 one screen along).
func (b *RegistryBrowser) entryFor(key string) *browserRegistryEntry {
	for i := range b.entries {
		if b.entries[i].key == key {
			return &b.entries[i]
		}
	}
	return nil
}

// registryFilterLabel returns a short display label for the active filter.
//
// D14: it used to search only the configured top-level entries, so filtering to
// a discovered member fell through to the synthesised URL — the one row in the
// view showing a URL where every other showed an alias. Members are entries now,
// so they resolve like anything else.
func (b *RegistryBrowser) registryFilterLabel() string {
	if b.registryFilter.groupSlug != "" {
		for _, reg := range b.registries {
			if reg.Slug == b.registryFilter.groupSlug {
				return browserAlias(reg)
			}
		}
		return b.registryFilter.groupSlug
	}
	if entry := b.entryFor(b.registryFilter.entryKey); entry != nil {
		if entry.ParentAlias != "" {
			return entry.ParentAlias + "/" + entry.Alias
		}
		if entry.Alias != "" {
			return entry.Alias
		}
		return registryRef(entry.URL, entry.repoPrefix)
	}
	return b.registryFilter.entryKey
}

// pullSelectedTag asks the parent to admit the pull as a job, mirroring
// requestDirectScan below.
//
package ociresources

import (
	"log"
	"time"

	tea "charm.land/bubbletea/v2"

	"github.com/anthnel/devdesk/internal/cache"
	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/registrymgr"
	"github.com/anthnel/devdesk/internal/trust"
)

// openMultiRegistryBrowser opens the multi-registry browser (triggered by 'b' on Images tab).
func (m Model) openMultiRegistryBrowser() (tea.Model, tea.Cmd) {
	if len(m.registries) == 0 {
		return m, m.footer.Warn("No registries configured — add one in the Registries tab")
	}
	// Config plus cache, read here and now: no network, no waiting, no state
	// that ignores esc (D13).
	m.registryBrowser = newRegistryBrowser(m.registries, m.groupCache, m.browserDeselected, m.width-2, m.height)
	m.registryBrowser.SetScanCache(m.scanCache)
	m.registryBrowser.SetJobs(m.jobs, m.failures, m.contextName)
	return m, nil
}

// closeMultiRegistryBrowser drops the browser, remembering what the user
// unchecked so the next visit opens on the same selection.
func (m Model) closeMultiRegistryBrowser() (tea.Model, tea.Cmd) {
	if m.registryBrowser == nil {
		return m, nil
	}
	deselected := m.registryBrowser.Deselected()
	m.registryBrowser = nil

	m.browserDeselected = make(map[string]bool, len(deselected))
	for _, key := range deselected {
		m.browserDeselected[key] = true
	}
	return m, saveBrowserSelectionCmd(deselected)
}

// handleMultiRegistryTagsLoaded incorporates tag results from one registry into the browser.
func (m Model) handleMultiRegistryTagsLoaded(msg MultiRegistryTagsLoadedMsg) (tea.Model, tea.Cmd) {
	if m.registryBrowser == nil {
		return m, nil
	}
	if msg.Err != nil {
		log.Printf("ERROR [oci_resources] registry tags %s from %s: %v", msg.Repo, msg.RegistryURL, msg.Err)
		m.registryBrowser.AddRegistryTags(msg.EntryKey, msg.RegistryURL, msg.Alias, msg.Repo, nil)
		return m, nil
	}
	m.registryBrowser.SetScanCache(m.scanCache)
	m.registryBrowser.AddRegistryTags(msg.EntryKey, msg.RegistryURL, msg.Alias, msg.Repo, msg.Tags)
	return m, loadMultiRegistryTagsMetaCmd(msg.EntryKey, msg.RegistryURL, msg.Repo)
}

// handleMultiRegistryTagsMeta stores tag metadata for one registry in the browser.
func (m Model) handleMultiRegistryTagsMeta(msg MultiRegistryTagsMetaMsg) (tea.Model, tea.Cmd) {
	if m.registryBrowser == nil {
		return m, nil
	}
	if msg.Err != nil {
		log.Printf("INFO [oci_resources] tag meta unavailable for %s at %s: %v", msg.Repo, msg.RegistryURL, msg.Err)
		return m, nil
	}
	if msg.Meta != nil {
		m.registryBrowser.SetMultiTagsMeta(msg.EntryKey, msg.Meta)
	}
	return m, nil
}

// handleRegistryPullRequested admits a browser pull as a job and puts the user
// where they can watch it: the Images tab, browser closed (§3.60).
//
// A pull is asked for from the browser and answered in the Images list, and
// leaving the user on the browser's own spinner meant the one screen that could
// not show either the progress or the result. The switch happens here, once, on
// the keypress that asked for it — it is not a work message dragging the screen
// around behind the user's back, which is what D67 forbids.
func (m Model) handleRegistryPullRequested(msg RegistryPullRequestedMsg) (tea.Model, tea.Cmd) {
	if m.pullingImage(msg.ImageName) {
		return m, m.footer.Warn("Pull already in progress")
	}
	start := jobs.Start(m.pullRun(msg.ImageName), pullOneImageCmd(msg.ImageName, m.pullDeps()))

	// closeMultiRegistryBrowser carries the deselection the next visit reopens
	// on, so the browser is closed through it rather than by hand.
	closed, closeCmd := m.closeMultiRegistryBrowser()
	next, ok := closed.(Model)
	if !ok {
		return closed, tea.Batch(closeCmd, start)
	}
	next.activeTab = tabImages
	next.updateImageTable()
	return next, tea.Batch(closeCmd, start)
}

// handleRegistryPullComplete processes the result of a pull.
//
// It does not depend on the browser any more: the pull outlives it now that
// asking for one closes it, and a completion that returned early on a nil
// browser would skip the refresh that makes the pulled image appear.
func (m Model) handleRegistryPullComplete(msg RegistryPullCompleteMsg) (tea.Model, tea.Cmd) {
	if msg.Replaces != "" {
		return m.handleImageUpdated(msg)
	}
	if isBlocked(msg.Err) {
		log.Printf("ERROR [oci_resources] pull %s refused: %v", msg.ImageName, msg.Err)
		return m, m.footer.Error("Pull of " + msg.ImageName + " refused: " + msg.Err.Error())
	}
	if msg.Err != nil {
		log.Printf("ERROR [oci_resources] pull %s: %v", msg.ImageName, msg.Err)
		return m, m.footer.Error("Pull failed — check logs")
	}
	if msg.Check.Decision == trust.Warn {
		return m, tea.Batch(fetchImages(), m.footer.Warn("Pulled "+msg.ImageName+" — "+msg.Check.Reason()))
	}
	return m, tea.Batch(fetchImages(), m.footer.Info("Image pulled: "+msg.ImageName))
}

// handleRegistryTagDirectScan starts a direct remote Trivy scan without pulling the image.
func (m Model) handleRegistryTagDirectScan(msg RegistryTagDirectScanMsg) (tea.Model, tea.Cmd) {
	if m.scanningImage(msg.ImageName) {
		return m, m.footer.Warn("Scan already in progress")
	}
	job := imageScanJob{Name: msg.ImageName, Target: msg.ImageName}
	return m, jobs.Start(
		m.scanRun([]string{msg.ImageName}),
		batchScanCmd([]imageScanJob{job}, m.scanOptions()),
	)
}

// unscannedCount returns the number of images not yet scanned
func (m *Model) unscannedCount() int {
	count := 0
	for _, img := range m.images {
		name := img.Name()
		if img.Repository == "<none>" {
			continue
		}
		if _, ok := m.scanCache[name]; !ok {
			count++
		}
	}
	return count
}

// handleRegistryGroupDetected records a discovery. Nothing forwards it to the
// browser any more: the browser reads the cache when it opens, so a refresh is
// something the Registries tab does and the Members column reports.
func (m Model) handleRegistryGroupDetected(msg RegistryGroupDetectedMsg) (tea.Model, tea.Cmd) {
	delete(m.refreshingGroups, msg.Slug)

	if msg.Err != nil {
		log.Printf("INFO [oci_resources] group detection failed for %s: %v", msg.RegistryURL, msg.Err)
		// The cache keeps what was last known rather than being emptied by an
		// unreachable manager, so the column keeps showing it — stale, and
		// visibly so.
		m.updateRegistryTable()
		return m, m.footer.Error("Group refresh failed — check logs")
	}
	if msg.Slug != "" {
		m.groupCache[msg.Slug] = cache.RegistryGroupEntry{
			Members:      toCachedMembers(msg.Members),
			DiscoveredAt: time.Now(),
		}
	}
	m.updateRegistryTable()
	return m, nil
}

// toCachedMembers converts what the detector returned into what the cache and
// the table hold.
func toCachedMembers(members []registrymgr.GroupMember) []cache.RegistryGroupMember {
	out := make([]cache.RegistryGroupMember, 0, len(members))
	for _, m := range members {
		out = append(out, cache.RegistryGroupMember{Alias: m.Alias, URL: m.URL, RepoPrefix: m.RepoPrefix})
	}
	return out
}

// handleRegistryGroupCacheLoaded takes the discoveries read from disk.
func (m Model) handleRegistryGroupCacheLoaded(msg RegistryGroupCacheLoadedMsg) (tea.Model, tea.Cmd) {
	if msg.Entries != nil {
		m.groupCache = msg.Entries
	}
	m.updateRegistryTable()
	return m, nil
}

