// handleSelectingKey is the clone selection mode (Rule 135 unchanged): `space`
// ticks, `←→` still drill, `enter` confirms.
//
// `esc` leaves the mode rather than drilling up, because cancelling is what the
// key means when there is something to cancel; `←` is still the way up.
func (m Model) handleSelectingKey(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case keymap.Space:
		return m.handleSelectionToggle()
	case "enter":
		return m.handleSelectionConfirm()
	case "esc":
		return m.handleSelectionCancel()
	case "left":
		return m.handleDrillUp()
	case "right":
		return m.handleDrillDown()
	}
	return m, m.table.Update(msg)
}

// handleCloningKey is the clone list: `esc` cancels, then closes. Navigation,
// `/` and `.` are the list's own table.
func (m Model) handleCloningKey(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
	if m.clone == nil {
		m.mode = ModeNormal
		return m, nil
	}
	// The list has its own filter bar, and its `esc` closes the search. Testing
	// the key first would cancel the run from inside the search box.
	if m.clone.table.InEditMode() {
		return m, m.clone.table.Update(msg)
	}
	if msg.String() == "esc" {
		return m.handleCloneEsc()
	}
	return m, m.clone.table.Update(msg)
}

// handleSpinnerTick advances the spinner the view owns, which is now the
// **load** and nothing else.
//
// It used to drive the clone rows as well, and that was the fourth hand-stamped
// chain D5 removed: the rows take the router's frame from the broadcast now, so
// a clone keeps turning whether or not this view is on screen — and cannot
// freeze on frame zero if this chain dies.
func (m Model) handleSpinnerTick(msg spinner.TickMsg) (tea.Model, tea.Cmd) {
**Why.** A cell is measured and truncated *before* it is dressed up, and the
measurement goes through `runewidth`, which counts an escape sequence's
bytes as width. A string of 7 visible cells carrying a color measures 28: it
therefore gets truncated in a column that is twice wide enough, and the cut
falls *inside* the escape sequence — `"\x1b[38;2;166;2…"`. The unterminated
sequence then bleeds onto every following row.

This is a limitation of `bubbles/table`, not of Bubble Tea or lipgloss, and
it is the same in Bubbles v2 (`charm.land/bubbles/v2`). `internal/ui/datatable` therefore
renders its own rows (`render.go`): the text is measured while still plain,
color is applied afterward. **The prohibition therefore targets `Cell`, not
color.**

```go
// ✅ CORRECT — the text is measurable, the color is decided separately
{
    Title: "Severity", MinWidth: 10,
    Cell:  func(f scan.Finding) string { return string(f.Severity) },
    Style: func(f scan.Finding) lipgloss.Style {
        return theme.SeverityTextStyle(string(f.Severity))
